def update_reservation_flights(reservation_id: str, cabin: str, flights: list, payment_id: str):
    """
    Update the flight information of a reservation.


    Args:
        reservation_id: The reservation ID, such as 'ZFA04Y'.
        cabin: The cabin class of the reservation, EXACTLY one of 'basic_economy', 'economy', or 'business'.
        flights: An array of objects containing details about each piece of flight in the ENTIRE new reservation. Even if a flight segment is not changed, it MUST still be included in the array. Each item MUST be an object with keys 'flight_number' and 'date' (format 'YYYY-MM-DD'), e.g. {"flight_number": "HAT023", "date": "2024-05-26"}.
        payment_id: The single payment id stored in the user profile, such as 'credit_card_7815826', 'gift_card_7815826'. It MUST be the EXACT, FULL id copied from the user's profile (never shortened or invented). A certificate CANNOT be used to pay for a flight change.

    Returns:
        The updated reservation.

    Raises:
        ValueError: If the reservation is not found.
        ValueError: If the user is not found.
        ValueError: If the payment method is not found.
        ValueError: If the certificate cannot be used to update reservation.
        ValueError: If the gift card balance is not enough.
    """
    def _user_methods():
        # Resolve the reservation's owner and return {payment_id: info}. Returns {}
        # on any failure (primitives return a plain string on a tool-level error).
        try:
            res = env_get_reservation_details(reservation_id=reservation_id)
        except Exception:
            return {}
        if not isinstance(res, dict):
            return {}
        uid = res.get("user_id")
        if not uid:
            return {}
        try:
            u = env_get_user_details(user_id=uid)
        except Exception:
            return {}
        if isinstance(u, dict) and isinstance(u.get("payment_methods"), dict):
            return u["payment_methods"]
        return {}

    def _fmt_methods(methods):
        parts = []
        for pid, info in methods.items():
            if isinstance(info, dict):
                src = info.get("source")
                amt = info.get("amount")
                if amt is not None:
                    parts.append(f"{pid} (source={src}, balance={amt})")
                else:
                    parts.append(f"{pid} (source={src})")
            else:
                parts.append(str(pid))
        return parts

    def _fix_id(pid, valid):
        # Correct a truncated payment id when it uniquely prefixes exactly one real
        # id. Fires only when pid is not already an exact match.
        if not isinstance(pid, str) or not valid or pid in valid:
            return pid
        matches = [v for v in valid if v.startswith(pid) or pid.startswith(v)]
        return matches[0] if len(matches) == 1 else pid

    result = env_update_reservation_flights(reservation_id=reservation_id, cabin=cabin, flights=flights, payment_id=payment_id)

    # ---- Recovery on a FAILED update only (success returns a reservation dict). ----
    if isinstance(result, str) and "Payment method not found" in result:
        valid = _user_methods()
        fixed = _fix_id(payment_id, valid)
        if fixed != payment_id:
            retry = env_update_reservation_flights(reservation_id=reservation_id, cabin=cabin, flights=flights, payment_id=fixed)
            if not isinstance(retry, str):
                return retry
            result = retry
        if isinstance(result, str) and "Payment method not found" in result and valid:
            usable = _fmt_methods({k: v for k, v in valid.items()
                                   if not (isinstance(v, dict) and v.get("source") == "certificate")})
            return (result + ". A flight change must be paid/refunded with ONE credit card or gift card "
                    "already on the user's profile (a certificate CANNOT be used). The user's usable "
                    "payment methods are: " + "; ".join(usable)
                    + ". Re-call update_reservation_flights with one of these EXACT payment_id values.")

    if isinstance(result, str) and "Certificate cannot be used" in result:
        valid = _user_methods()
        usable = _fmt_methods({k: v for k, v in valid.items()
                               if not (isinstance(v, dict) and v.get("source") == "certificate")}) if valid else []
        extra = (" The user's usable (non-certificate) payment methods are: " + "; ".join(usable)) if usable else ""
        return (result + ". A flight change must be paid with ONE credit card or gift card, not a certificate."
                + extra)

    if isinstance(result, str) and ("Not enough seats" in result or "not available" in result or "not found on date" in result):
        return (result + ". Use search_direct_flight / search_onestop_flight to find an available "
                "flight/date/cabin with enough seats before updating again.")

    return result
